	@Inject
	public LatinoGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pPrograma = new ProgramaElements();
		this.pSentenciaPrincipal = new SentenciaPrincipalElements();
		this.pSentencia = new SentenciaElements();
		this.pAsignacion = new AsignacionElements();
		this.pLeer = new LeerElements();
		this.eConversion = new ConversionElements();
		this.pLista = new ListaElements();
		this.pAsignacionIndice = new AsignacionIndiceElements();
		this.pCondicional = new CondicionalElements();
		this.pOsi = new OsiElements();
		this.pMientras = new MientrasElements();
		this.pRepetir = new RepetirElements();
		this.pDesde = new DesdeElements();
		this.pPara = new ParaElements();
		this.pVariable = new VariableElements();
		this.pIncremento = new IncrementoElements();
		this.eOperadorPaso = new OperadorPasoElements();
		this.pRomper = new RomperElements();
		this.pContinuar = new ContinuarElements();
		this.pElegir = new ElegirElements();
		this.pCaso = new CasoElements();
		this.pConstante = new ConstanteElements();
		this.pFuncion = new FuncionElements();
		this.pRetorno = new RetornoElements();
		this.pLlamada = new LlamadaElements();
		this.pImprimir = new ImprimirElements();
		this.pExpresion = new ExpresionElements();
		this.pConjuncion = new ConjuncionElements();
		this.pComparacion = new ComparacionElements();
		this.pConcatenacion = new ConcatenacionElements();
		this.pSuma = new SumaElements();
		this.pProducto = new ProductoElements();
		this.pUnario = new UnarioElements();
		this.pPrimario = new PrimarioElements();
		this.pNumero = new NumeroElements();
		this.tSL_COMMENT = (TerminalRule) GrammarUtil.findRuleForName(getGrammar(), "uta.latino.Latino.SL_COMMENT");
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("uta.latino.Latino".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
